import Foundation

struct ReadingEntry: Codable, Equatable {
    let title: String
    let minutes: Int
}

let entries = [ReadingEntry(title: "Geography", minutes: 25)]
let url = FileManager.default.temporaryDirectory
    .appendingPathComponent("reading-example.json")

do {
    let data = try JSONEncoder().encode(entries)
    try data.write(to: url, options: .atomic)
    let storedData = try Data(contentsOf: url)
    let restored = try JSONDecoder().decode([ReadingEntry].self, from: storedData)
    print(restored == entries)
    print(FileManager.default.fileExists(atPath: url.path))
} catch {
    print("Saved entries could not be read or written")
}

import Foundation
struct PracticeEntry: Codable, Equatable {
 let title: String
 let minutes: Int
}
func loadEntries(_ bytes: Data) -> (entries: [PracticeEntry], message: String) {
 do {
  return (try JSONDecoder().decode([PracticeEntry].self, from: bytes), "Loaded")
 } catch { return ([], "Entries could not be read") }
}
func loadEntries(from url: URL) -> (entries: [PracticeEntry], message: String) {
 do { return loadEntries(try Data(contentsOf: url)) }
 catch { return ([], "Entries could not be read") }
}
let entries = [PracticeEntry(title: "Swift", minutes: 20)]
let url = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString + ".json")
defer { try? FileManager.default.removeItem(at: url) }
do {
 try JSONEncoder().encode(entries).write(to: url, options: .atomic)
 print(loadEntries(from: url).entries == entries)
 print(loadEntries(Data("broken".utf8)).message)
} catch { print("Entries could not be saved") }

struct LookupResult {
    let index: Int?
    let comparisons: Int
}

func locate(_ target: Int, in values: [Int]) -> LookupResult {
    var comparisons = 0
    for (index, value) in values.enumerated() {
        comparisons += 1
        if value == target {
            return LookupResult(index: index, comparisons: comparisons)
        }
    }
    return LookupResult(index: nil, comparisons: comparisons)
}

let values = [4, 8, 12, 16]
let found = locate(12, in: values)
let missing = locate(20, in: values)
print(found.index ?? -1)
print(found.comparisons)
print(missing.index == nil)
print(missing.comparisons)

