enum Download {
    case idle
    case receiving(bytes: Int)
}
func description(_ download: Download) -> String {
    switch download {
    case .idle: return "Not started"
    case .receiving(let bytes): return "Received \(bytes) bytes"
    }
}
print(description(.receiving(bytes: 24)))

enum Delivery { case waiting; case travelling(minutes: Int); case arrived }
func deliveryMessage(_ state: Delivery) -> String {
 switch state {
 case .waiting: return "Waiting"
