enum MinutesError: Error { case negative }
final class Trace { var events: [String] = [] }
func checkedMinutes(_ minutes: Int, trace: Trace) throws -> Int {
 trace.events.append("started")
 defer { trace.events.append("finished") }
 if minutes < 0 { throw MinutesError.negative }
 return minutes
}
func inspectMinutes(_ minutes: Int) -> [String] {
 let trace = Trace()
 do {
  let value = try checkedMinutes(minutes, trace: trace)
  trace.events.append("accepted: \(value)")
 } catch { trace.events.append("rejected") }
 return trace.events
}
print(inspectMinutes(0))
